        def boom(url):
            raise OSError("connection refused")

        monkeypatch.setattr("registry_lookup._fetch_json", boom)
        with pytest.raises(LicenseLookupError, match="left-pad"):
            npm_license_lookup("left-pad", "1.3.0")


