        # is the more trustworthy signal, so it should win when present.
        monkeypatch.setattr(
            "registry_lookup._fetch_json",
            lambda url: {
                "info": {
                    "license": "Copyright Foo Corp",
                    "classifiers": [
                        "Programming Language :: Python :: 3",
                        "License :: OSI Approved :: MIT License",
                    ],
                }
            },
        )
